//! AUTOGENERATED - DO NOT EDIT
//! In-process FFI entry for Bb: the ipc-codegen FFI backend contract, with the
//! symbols prefixed by the service so several services can be linked into one binary.
//!
//! `export_bb_ffi!` defines the exported C-ABI symbols `bb_ipc_ffi_entry`, `bb_ipc_ffi_alloc` and
//! `bb_ipc_ffi_free` over one handler, built with `Default` on the first call and kept for the life
//! of the process, so stateful command sequences share state the way they would on one transport
//! connection. Invoke it once at the crate root of a `cdylib`/`staticlib`, or of a wasm reactor:
//!
//! ```ignore
//! export_bb_ffi!(crate::generated::bb_ffi, MyHandler);
//! ```
//!
//! Needs the `libc` crate for the malloc-compatible buffers.

use super::bb_server::{handle_request, Handler};

/// One FFI round trip: decode and dispatch `input`, leaving the response payload in a buffer
/// from [`ffi_alloc`] that the caller releases with [`ffi_free`].
///
/// # Safety
/// `input` must be valid for `input_len` bytes; `output` and `output_len` must be valid for writes.
pub unsafe fn ffi_call(
    handler: &mut dyn Handler,
    input: *const u8,
    input_len: usize,
    output: *mut *mut u8,
    output_len: *mut usize,
) {
    let request: &[u8] = if input_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(input, input_len) }
    };
    let response = handle_request(handler, request);
    let buf = ffi_alloc(response.len());
    unsafe {
        std::ptr::copy_nonoverlapping(response.as_ptr(), buf, response.len());
        *output = buf;
        *output_len = response.len();
    }
}

/// malloc-compatible allocation for buffers crossing the FFI boundary in either direction.
pub fn ffi_alloc(size: usize) -> *mut u8 {
    // A zero-size request still yields a distinct, freeable pointer.
    unsafe { libc::malloc(size.max(1)) as *mut u8 }
}

/// Release a buffer from [`ffi_alloc`].
///
/// # Safety
/// `ptr` must have come from [`ffi_alloc`] and not have been freed already.
pub unsafe fn ffi_free(ptr: *mut u8) {
    unsafe { libc::free(ptr as *mut libc::c_void) };
}

/// Define the exported C-ABI FFI symbols over `$handler` (a `Handler + Default + Send` type).
/// `$ffi` is the path of this module, which the expansion calls back into.
#[macro_export]
macro_rules! export_bb_ffi {
    ($ffi:path, $handler:ty) => {
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn bb_ipc_ffi_entry(
            input: *const u8,
            input_len: usize,
            output: *mut *mut u8,
            output_len: *mut usize,
        ) {
            use $ffi as ffi;
            static HANDLER: ::std::sync::Mutex<Option<$handler>> = ::std::sync::Mutex::new(None);
            let mut guard = HANDLER.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
            let handler = guard.get_or_insert_with(<$handler as ::std::default::Default>::default);
            unsafe { ffi::ffi_call(handler, input, input_len, output, output_len) };
        }

        #[unsafe(no_mangle)]
        pub extern "C" fn bb_ipc_ffi_alloc(size: usize) -> *mut u8 {
            use $ffi as ffi;
            ffi::ffi_alloc(size)
        }

        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn bb_ipc_ffi_free(ptr: *mut u8) {
            use $ffi as ffi;
            unsafe { ffi::ffi_free(ptr) };
        }
    };
}
